---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Knowledge sources: The files, sites and folders the agent knows, and how far each is indexed.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change knowledge-sources.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './knowledge-sources.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="knowledge-sources" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ksx panel" data-reveal="flat">
  <div class="ksx-h"><span class="ksx-hi" aria-hidden="true"><svg class="i xs"><use href="#i-book"/></svg></span><div><b>Knowledge sources</b><span class="muted ksx-st" aria-live="polite"></span></div></div>
  <div class="ksx-list" role="list" aria-label="Sources"></div>
  <div class="ksx-em"><span class="ksx-em-art" aria-hidden="true"></span><b>No sources yet</b><span>Add files, a website or a folder, and the agent reads them.</span><button class="pill line sm ksx-add2" data-pop=".ksx-pop" aria-haspopup="menu" aria-expanded="false"><svg class="i xs"><use href="#i-plus"/></svg>Add source</button></div>
  <div class="ksx-ft"><button class="ksx-add" data-pop=".ksx-pop" aria-haspopup="menu" aria-expanded="false"><svg class="i xs"><use href="#i-plus"/></svg>Add source</button></div>
  <div class="pop ksx-pop" role="menu" aria-label="Add source"></div>
  <div class="pop ksx-mpop" role="menu" aria-label="Source actions"><button class="mi ksx-rs" role="menuitem" data-close><svg class="i xs"><use href="#i-refresh"/></svg>Re-sync</button><div class="sep"></div><button class="mi del ksx-rm" role="menuitem" data-close><svg class="i xs"><use href="#i-trash"/></svg>Remove</button></div>
  <input class="ksx-file" type="file" multiple hidden>
</div>
  </Fragment></div>
</div>
<script>
  import './knowledge-sources.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Knowledge sources ---------- */
/* what the agent knows: each source with its type, its size and how far it is indexed. The card sits on two columns (owner,
   18 Nov), its content 16px from every edge: the head's neutral mark in a 28px column with each source's mark under it, and
   the title and each source's words 12px after it; the menu buttons' glyphs end on the content's right edge. A row is not a
   button, so it has no hover fill. The line under a source's name is its state, led by its mark (beside it, never over the
   source's own): a green tick and what it holds once it is indexed, a clock while it waits, a bar and a count that shimmers
   while it is read, and a red sign with the reason once it has failed, with a fix under it. A type's mark is a vivid tile of
   its colour with white or the colour's own ink on it. The card grows and shrinks with its rows (grow()) */
.ksx{padding:var(--dm-s-4);display:flex;flex-direction:column}
.ksx.growing:has(.pop.open){overflow:visible}
.ksx-h{display:flex;align-items:center;gap:var(--dm-s-3);padding-bottom:var(--dm-s-2)}
.ksx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));color:var(--dm-fg2);background:var(--dm-chip)}
.ksx-h>div{flex:1;display:flex;flex-direction:column;min-width:0}
.ksx-h b{font-weight:500;font-size:14px;line-height:20px}
.ksx-st{font-size:12px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ksx-list{display:flex;flex-direction:column}
.ksx-s{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 0;font-size:13px}
.ksx-s .ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center}
.ksx-s .t{min-width:0;display:flex;flex-direction:column}
.ksx-s .nm{line-height:20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ksx-s .d{display:flex;align-items:center;gap:5px;min-width:0;height:18px;font-size:12px;color:var(--dm-muted)}
.ksx-s .d>span:last-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ksx-s .d>.i{flex:none;color:var(--dm-muted)}
.ksx-s[data-st="ready"] .d>.i{color:var(--dm-ok-mark)}
.ksx-s[data-st="failed"] .d{color:var(--dm-bad)}
/* why it failed is never cut short: on a narrow card it wraps, its sign on the first line */
.ksx-s[data-st="failed"] .d{height:auto;min-height:18px;align-items:flex-start;line-height:18px}
.ksx-s[data-st="failed"] .d>.i{margin-top:3px}
.ksx-s[data-st="failed"] .d>span:last-child{white-space:normal;text-wrap:pretty}
.ksx-s[data-st="failed"] .d>.i{color:var(--dm-bad-mark)}
.ksx-s .d .shim{font-size:inherit}
.ksx-s[data-st="indexing"] .d{gap:var(--dm-s-2)}
.ksx-bar{width:56px;height:4px;border-radius:var(--dm-r-tiny,2px);background:var(--dm-line);overflow:hidden;flex:none}
.ksx-bar i{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark,var(--dm-accent));transition:width .2s linear}
/* the menu button: its hover circle ends on the content's right edge (a box that fills keeps the card's 16px) */
.ksx-more{width:28px;height:28px}
.ksx-s .ksx-fx{grid-column:2/-1}
.ksx-fx>div{overflow-clip-margin:0px}
.ksx-fx>div>div{display:flex;flex-wrap:wrap;gap:6px;padding-top:var(--dm-s-2)}
/* Add source: its + centred in the marks' column and its words on the title's; the hover box starts on the content's edge */
.ksx-add{display:flex;align-items:center;gap:var(--dm-s-3);align-self:flex-start;height:32px;margin-top:var(--dm-s-1);padding:0 var(--dm-s-3) 0 0;font-size:13px;color:var(--dm-fg2);border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
.ksx-add>.i{width:28px;padding:0 8px;box-sizing:border-box}
.ksx-add[aria-expanded="true"]{color:var(--dm-fg);background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.ksx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.ksx-pop{width:248px}
.ksx-mpop{min-width:160px}
.ksx-mpop .mi.del,.ksx-mpop .mi.del .i{color:var(--dm-bad)}
@media (hover:hover) and (pointer:fine){.ksx-mpop .mi.del:hover{background:var(--dm-bad-bg)}}
.ksx-mpop .mi[disabled],.ksx-mpop .mi[disabled] .i{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
.ksx-web{display:flex;flex-direction:column;gap:var(--dm-s-1)}
/* (the field holds the site's small button, 28px, with 4px round it) */
.ksx-in{display:flex;align-items:center;gap:var(--dm-s-2);height:36px;margin:0 2px 2px;padding:0 var(--dm-s-1) 0 10px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.ksx-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.ksx-in:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.ksx-in input{flex:1;min-width:0;height:100%;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.ksx-in input::placeholder{color:var(--dm-muted)}
/* nothing left: the empty state (the lab's, lab/clean): a small sketch of the list on a white card, a title, one muted line
   and Add source as an outline button */
.ksx-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:16px 16px 20px;text-align:center}
.ksx-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.ksx-em>span:not(.ksx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.ksx-em .pill{margin-top:12px}
.ksx-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 16px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.ksx-em-art::before{content:"";position:absolute;left:14px;top:13px;width:12px;height:12px;border-radius:4px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
.ksx-em-art::after{content:"";position:absolute;left:34px;top:16px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,var(--dm-wash))}
.ksx-list:not(:empty)~.ksx-em,.ksx-list:empty~.ksx-ft{display:none}
/* the foot sits under a hairline in Soft and Blueprint (owner, 21 Nov), its button's words 16px from the hairline and 16px from
   the card's bottom edge (owner, 23 Nov): the ghost button's 32px box reaches 6px round its words, so the foot has 10px above it
   and reaches 6px into the card's bottom padding. Clean's is a foot strip */
.ksx-ft{margin-bottom:-6px;padding-top:10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ksx-ft .ksx-add{margin-top:0}
.shx-ft{margin-bottom:-6px;padding-top:10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.shx-ft .shx-add{margin-top:0}
:root:not([data-style="soft"],[data-style="clean"]) .ksx-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-rail) 60%,transparent)}
:root:not([data-style="soft"],[data-style="clean"]) :is(.ksx-em-art::before,.ksx-em-art::after):not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:0}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.ksx :is(.ib,.pill):active,:root[data-style="clean"] .ksx .ib:active,:root [data-style="clean"] .ksx .ib:active,:root [data-style="clean"].ksx .ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): the head an off-white strip with a hairline under it; the sources' marks one neutral grey
   with a hairline; Add source a flat secondary button on an off-white foot strip, 16px from the card's edges and the
   strip's hairline (owner, 23 Nov); the content 16px
   in from each edge and 16px from each strip; menus scale and fade from their button, with the card's corners */
:root[data-style="clean"] .ksx.panel,:root [data-style="clean"] .ksx.panel,:root [data-style="clean"].ksx.panel{padding:0}
:root[data-style="clean"] .ksx-h,:root [data-style="clean"] .ksx-h,:root [data-style="clean"].ksx-h{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .ksx-hi,:root [data-style="clean"] .ksx-hi,:root [data-style="clean"].ksx-hi{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .ksx-list,:root [data-style="clean"] .ksx-list,:root [data-style="clean"].ksx-list{padding:var(--dm-s-2) var(--dm-s-4)}
:root[data-style="clean"] .ksx-list:empty,:root [data-style="clean"] .ksx-list:empty,:root [data-style="clean"].ksx-list:empty{padding:0}
:root[data-style="clean"] .ksx-s .ic,:root [data-style="clean"] .ksx-s .ic,:root [data-style="clean"].ksx-s .ic{background:var(--dm-surface)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .ksx-s[data-st="ready"] .d>.i,:root [data-style="clean"] .ksx-s[data-st="ready"] .d>.i,:root [data-style="clean"].ksx-s[data-st="ready"] .d>.i{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .ksx-ft,:root [data-style="clean"] .ksx-ft,:root [data-style="clean"].ksx-ft{margin-bottom:0;padding:var(--dm-strip-y) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .ksx-add,:root [data-style="clean"] .ksx-add,:root [data-style="clean"].ksx-add{gap:6px;height:28px;margin:0;padding:0 12px 0 10px;border-radius:var(--dm-r-pill);font-weight:500;color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .ksx-add>.i,:root [data-style="clean"] .ksx-add>.i,:root [data-style="clean"].ksx-add>.i{width:12px;padding:0}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] :is(.ksx-add:hover,.ksx-add[aria-expanded="true"]),:root [data-style="clean"] :is(.ksx-add:hover,.ksx-add[aria-expanded="true"]),:root [data-style="clean"]:is(.ksx-add:hover,.ksx-add[aria-expanded="true"]){background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ksx-add:active,:root [data-style="clean"] .ksx-add:active,:root [data-style="clean"].ksx-add:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .ksx .pill.ghost:not([disabled]),:root [data-style="clean"] .ksx .pill.ghost:not([disabled]),:root [data-style="clean"].ksx .pill.ghost:not([disabled]){color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ksx .pill.ghost:not([disabled]):hover,:root [data-style="clean"] .ksx .pill.ghost:not([disabled]):hover,:root [data-style="clean"].ksx .pill.ghost:not([disabled]):hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ksx .pill.ghost:not([disabled]):active,:root [data-style="clean"] .ksx .pill.ghost:not([disabled]):active,:root [data-style="clean"].ksx .pill.ghost:not([disabled]):active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] :is(.ksx-pop,.ksx-mpop),:root [data-style="clean"] :is(.ksx-pop,.ksx-mpop),:root [data-style="clean"]:is(.ksx-pop,.ksx-mpop){padding:6px;border-radius:var(--dm-r-card)}
:root[data-style="clean"] :is(.ksx-pop,.ksx-mpop) .mi,:root [data-style="clean"] :is(.ksx-pop,.ksx-mpop) .mi,:root [data-style="clean"]:is(.ksx-pop,.ksx-mpop) .mi{border-radius:calc(var(--dm-r-card) - 6px)}
:root[data-style="clean"] .ksx-pop .ph,:root [data-style="clean"] .ksx-pop .ph,:root [data-style="clean"].ksx-pop .ph{padding-inline:10px}
:root[data-style="clean"] .ksx-in,:root [data-style="clean"] .ksx-in,:root [data-style="clean"].ksx-in{margin:0;padding-right:var(--dm-s-1);border-radius:calc(var(--dm-r-card) - 6px)}
:root[data-style="clean"] .ksx-em,:root [data-style="clean"] .ksx-em,:root [data-style="clean"].ksx-em{padding:28px 16px 30px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, closePops, enter, grow, hoverGlide, html, placePop, popRoom, stagger, swap } from '../core/core.js';
DM.def('knowledge-sources', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{plus\}/g, I('plus','xs')).replace('{refresh}', I('refresh','xs')).replace('{trash}', I('trash','xs')).replace('{book}', I('book','xs'));
  // Clean's one hover: a highlight that glides from row to row (hoverGlide)
  c.offs.push(hoverGlide($('.ksx-list', r), '.ksx-s'));
  // a source's type gives it its icon, on a vivid tile of its colour: uploaded files, a website the agent crawls, or a
  // connected folder of docs
  const KIND = { files:['file-text','p'], web:['globe','b'], folder:['folder','m'] };
  // a connected folder and a set of uploads are ready, and a PDF is being read. One source indexes at a time and the rest
  // wait in line; a source's chunks count once it has been indexed. `ms` is how long a full pass takes in this preview
  const S = [
    { kind:'folder', name:'Product docs', n:86, unit:'pages', chunks:642, st:'ready', ago:'2m ago', had:true, ms:2500 },
    { kind:'files', name:'Sales playbooks', n:18, unit:'files', chunks:318, st:'ready', ago:'1h ago', had:true, ms:2500 },
    { kind:'files', name:'Brand book 2024.pdf', n:24, unit:'pages', chunks:48, st:'queued', ms:19000, fail:{ at:9, why:'Scanned PDF, no text found', fix:'Retry with OCR' } }
  ];
  const FOLDERS = [['Design specs', 'Google Drive', 57, 230], ['Research notes', 'Notion', 31, 124]];
  const root = $('.ksx', r) || r, list = $('.ksx-list', r), st = $('.ksx-st', r), pop = $('.ksx-pop', r), mpop = $('.ksx-mpop', r), file = $('.ksx-file', r);
  // Add source sits under the list, and in the empty state once every source is gone; both open the same menu
  const add = $('.ksx-add', r), adds = $$('.ksx-add,.ksx-add2', r); let from = add;
  const fmt = n => n.toLocaleString('en-US');
  const of = (n, unit) => fmt(n) + ' ' + (n === 1 ? unit.slice(0, -1) : unit);
  const esc = t => t.replace(/&/g, '&amp;').replace(/</g, '&lt;');
  // the line under a source's name, led by its state's mark: a tick once indexed, a clock while it waits, a sign when it failed
  const line = x => x.st === 'queued' ? I('clock','xs') + `<span>${x.ocr ? 'Queued to read with OCR' : 'Queued'}</span>`
    : x.st === 'failed' ? I('alert','xs') + `<span>${esc(x.fail.why)}</span>` : I('ok','xs') + `<span>${of(x.n, x.unit)} · Synced ${x.ago}</span>`;
  function row(x){
    const [ic, k] = KIND[x.kind];
    x.el = html(`<div class="ksx-s" role="listitem"><span class="ic" style="background:var(--dm-av-${k});color:var(--dm-av-${k}-ink)" aria-hidden="true">${I(ic,'xs')}</span><span class="t"><span class="nm"></span><span class="d"></span></span><button class="ib ksx-more" aria-haspopup="menu" aria-expanded="false" data-tip="More" data-pop=".ksx-mpop" data-pop-align="end">${I('more')}</button><div class="ksx-fx fold shut" inert><div><div><button class="pill accent sm ksx-fix"></button><button class="pill ghost sm ksx-del">Remove</button></div></div></div></div>`);
    $('.nm', x.el).textContent = x.name; $('.ksx-more', x.el).setAttribute('aria-label', 'Actions for ' + x.name);
    $('.ksx-fix', x.el).onclick = () => { x.ocr = true; x.st = 'queued'; x.ms = 3000; paint(x); next(); };
    $('.ksx-del', x.el).onclick = () => remove(x);
    paint(x, true); return x.el;
  }
  // the progress bar and its count, while a source is being indexed; the count shimmers, as every line of a process at work
  function prog(x){
    const bar = $('.ksx-bar', x.el); if (!bar) return; const k = Math.floor(x.done);
    $('i', bar).style.width = k / x.n * 100 + '%'; bar.setAttribute('aria-valuenow', k);
    $('.num', x.el).textContent = fmt(k) + ' of ' + of(x.n, x.unit);
  }
  function paint(x, now){
    const d = $('.d', x.el); x.el.dataset.st = x.st;
    // the bar goes through the same swap as the line before it, so a line still swapping in can't land on top of it
    if (x.st === 'indexing'){ const bar = `<span class="ksx-bar" role="progressbar" aria-label="Indexing ${x.name.replace(/[<&"]/g, '')}" aria-valuemin="0" aria-valuemax="${x.n}"><i style="width:0"></i></span><span class="num shim"></span>`; if (now){ d.innerHTML = bar; prog(x); } else swap(d, bar, true); }
    else if (now) d.innerHTML = line(x); else swap(d, line(x), true);
    const fx = $('.ksx-fx', x.el), on = x.st === 'failed';
    if (on) $('.ksx-fix', x.el).textContent = x.fail.fix;
    fx.classList.toggle('shut', !on); fx.inert = !on;
  }
  // the line under the title says what the list doesn't: how much of it the agent can search, once it is indexed
  const total = () => `${fmt(S.reduce((a, x) => a + (x.had ? x.chunks : 0), 0))} chunks indexed`;
  const counts = now => { if (now) st.textContent = total(); else swap(st, total()); };
  // the one being indexed moves on every tick; a scanned PDF stops where its text runs out, until it is read with OCR
  function next(){
    if (S.some(x => x.st === 'indexing')) return;
    const x = S.find(y => y.st === 'queued'); if (!x) return;
    x.st = 'indexing'; x.done = 0; paint(x);
  }
  c.every(100, () => {
    const x = S.find(y => y.st === 'indexing'); if (!x) return;
    x.done = Math.min(x.n, x.done + x.n * 100 / x.ms);
    if (x.fail && !x.ocr && x.done >= x.fail.at){ x.st = 'failed'; paint(x); counts(); return next(); }
    prog(x);
    if (x.done >= x.n){ x.st = 'ready'; x.ago = 'just now'; x.had = true; paint(x); counts(); next(); }
  });
  function addSource(x){ x.st = 'queued'; S.push(x); list.appendChild(row(x)); enter(x.el); counts(); next(); }
  function remove(x){
    const i = S.indexOf(x); if (i < 0) return; S.splice(i, 1); counts(); next();
    x.el.classList.add('leave'); c.later(REDUCE ? 0 : 340, () => x.el.remove());
  }
  S.forEach(x => list.appendChild(row(x))); stagger([...list.children], 50); counts(true); next();
  // Re-sync and Remove act on the row whose button opened the menu; a source still waiting or indexing can't be re-synced yet
  let cur = null;
  c.on(list, 'click', e => { const b = e.target.closest('.ksx-more'); if (!b) return; cur = S.find(x => x.el.contains(b)); $('.ksx-rs', mpop).disabled = !cur || cur.st === 'queued' || cur.st === 'indexing'; if (!mpop.classList.contains('open')) side(b, mpop); });
  $('.ksx-rs', mpop).onclick = () => { if (!cur || !S.includes(cur)) return; cur.st = 'queued'; cur.ms = cur.ocr ? 3000 : cur.fail ? 19000 : 2500; paint(cur); next(); };
  $('.ksx-rm', mpop).onclick = () => cur && remove(cur);
  // Add source: upload files (the file picker), add a website (its address), or connect a folder (from the ones offered)
  function view(v){
    if (v === 'web') pop.innerHTML = `<form class="ksx-web"><div class="ph">Add a website</div><div class="ksx-in">${I('globe','xs')}<input placeholder="example.com/docs" aria-label="Website address" spellcheck="false" autocomplete="off"><button class="pill accent sm" type="submit">Add</button></div></form>`;
    else if (v === 'folder') pop.innerHTML = '<div class="ph">Connect a folder</div>' + (FOLDERS.length ? FOLDERS.map((f, i) => `<button class="mi" role="menuitem" data-close data-i="${i}">${I('folder','xs')}<span>${f[0]}<span class="d">${f[1]}</span></span></button>`).join('') : '<div class="ph">All folders connected</div>');
    else pop.innerHTML = [['upload', 'Upload files', 'files'], ['globe', 'Add a website', 'web'], ['folder', 'Connect a folder', 'folder']].map(([ic, t, k]) => `<button class="mi" role="menuitem" data-v="${k}"${k === 'files' ? ' data-close' : ''}>${I(ic,'xs')}<span>${t}</span></button>`).join('');
  }
  view('main');
  // a menu opens over the card from its button: down when it fits below, up when it doesn't and fits above or has more room
  // there (as placePop), within the stage's room, so it never spills over the card's caption under the stage (as Artifact
  // card's version menu). The side is set on the button just before the menu is placed
  const side = (btn, pop) => { const room = popRoom(btn), st = btn.closest('.stage-inner') || btn.closest('.stage');
    if (st){ const sr = st.getBoundingClientRect(), cs = getComputedStyle(st); room.top = Math.max(room.top, sr.top + parseFloat(cs.paddingTop)); room.bottom = Math.min(room.bottom, sr.bottom - parseFloat(cs.paddingBottom)); }
    const br = btn.getBoundingClientRect(), need = pop.offsetHeight + 12, below = room.bottom - br.bottom, above = br.top - room.top;
    btn.dataset.popPos = below < need && (above >= need || above > below) ? 'up' : 'down'; };
  adds.forEach(b => c.on(b, 'click', () => { from = b; if (!pop.classList.contains('open')){ view('main'); side(b, pop); } }));
  // a step inside the menu swaps its content after the click has been handled, so the click still counts as inside it. The
  // menu keeps the side it opened on: one that opened upwards grows upwards, held by its bottom edge
  const replace = () => { if (!(pop.style.getPropertyValue('--dm-origin') || '').startsWith('bottom')) side(from, pop); placePop(from, pop); };
  c.on(pop, 'click', e => {
    const m = e.target.closest('.mi'); if (!m) return;
    if (m.dataset.v === 'files') return file.click();
    if (m.dataset.v){ const v = m.dataset.v, mine = e.isTrusted; c.later(0, () => { view(v); replace(); if (mine && v === 'web') $('input', pop).focus({ preventScroll:true }); }); return; }
    if (m.dataset.i){ const f = FOLDERS.splice(+m.dataset.i, 1)[0]; addSource({ kind:'folder', name:f[0], n:f[2], unit:'pages', chunks:f[3], ms:3000 }); }
  });
  c.on(pop, 'submit', e => {
    e.preventDefault(); const inp = $('input', pop), v = inp.value.trim().replace(/^https?:\/\//, '').replace(/\/$/, '');
    if (!v) return inp.focus();
    closePops(); addSource({ kind:'web', name:v, n:142, unit:'pages', chunks:196, ms:4500 });
  });
  file.onchange = () => { const fs = [...file.files]; if (!fs.length) return;
    addSource({ kind:'files', name:fs.length === 1 ? fs[0].name : fs.length + ' files', n:fs.length, unit:'files', chunks:fs.length * 12, ms:1500 }); file.value = ''; };
  // the card grows with its rows and shrinks as they go (owner, 17 Nov: no room kept for a later state)
  c.offs.push(grow(root));
  // the preview's story: add the docs site, which waits its turn; the PDF turns out to be a scan, so read it with OCR, and
  // everything ends up indexed
  c.story(async s => {
    const pdf = S[2];
    await s.beat(3);
    await s.tap(add); await s.beat(2);
    await s.tap($('.mi[data-v="web"]', pop)); await s.beat(1);
    const inp = $('input', pop);
    await s.type(inp, 'designme.dev/docs', { n:.1, keep:true });
    await s.beat(1);
    await s.tap($('button[type="submit"]', pop)); s.away();
    await s.until(() => pdf.st === 'failed'); await s.beat(2);
    await s.tap($('.ksx-fix', pdf.el)); s.away();
    await s.until(() => S.every(x => x.st === 'ready')); await s.beat(1);
  });
});
